{
  "missing_information": [
    {
      "category": "Trigger Definition",
      "gap": "It is unclear what event or condition officially marks the end of a meeting and triggers the summarization process.",
      "why_it_matters": "Without a clear trigger, it is impossible to determine when the workflow starts or how to automate handoff from meeting to summary creation."
    },
    {
      "category": "Summary Creation Method",
      "gap": "There is no information on how the meeting summary is produced — manually by a participant, by a designated note-taker, or via an automated transcription or AI tool.",
      "why_it_matters": "The method of creation directly determines the automation potential and the tools or integrations required."
    },
    {
      "category": "Summary Content and Structure",
      "gap": "The required content and format of the summary (e.g., action items, decisions, attendees, agenda points) are not defined.",
      "why_it_matters": "Inconsistent or undefined structure makes it difficult to automate generation, validate completeness, or parse outputs downstream."
    },
    {
      "category": "Recipient Determination",
      "gap": "The criteria for identifying 'relevant people' who receive the email are not specified — it is unknown whether this is the attendee list, a predefined distribution list, or a manual selection.",
      "why_it_matters": "Recipient logic must be explicit to automate email distribution and avoid over- or under-sharing of information."
    },
    {
      "category": "Review and Approval Step",
      "gap": "It is unclear whether the summary goes through any review or approval before being sent, and if so, who is responsible.",
      "why_it_matters": "An approval gate changes the workflow structure significantly and affects timing, accountability, and automation design."
    },
    {
      "category": "Timing and SLA",
      "gap": "There is no information on the expected or required time between the end of the meeting and the delivery of the summary email.",
      "why_it_matters": "Time constraints determine urgency, influence tool selection, and are needed to identify bottlenecks or SLA compliance risks."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What event or action officially signals that a meeting has ended and that the summarization process should begin?",
      "targets": ["Trigger Definition"]
    },
    {
      "id": "Q2",
      "question": "How is the meeting summary currently created — for example, is it written manually by a participant, produced by a dedicated note-taker, or generated using a transcription or AI tool?",
      "targets": ["Summary Creation Method"]
    },
    {
      "id": "Q3",
      "question": "What specific sections or elements are required in a meeting summary, such as decisions made, action items with owners, agenda topics covered, or attendee list?",
      "targets": ["Summary Content and Structure"]
    },
    {
      "id": "Q4",
      "question": "How are the recipients of the summary email determined — is it automatically taken from the meeting attendee list, a predefined group, or manually selected each time?",
      "targets": ["Recipient Determination"]
    },
    {
      "id": "Q5",
      "question": "Before the summary email is sent, does anyone need to review or approve the content, and if so, who holds that responsibility?",
      "targets": ["Review and Approval Step"]
    },
    {
      "id": "Q6",
      "question": "Is there a defined time limit within which the summary email must be sent after the meeting concludes, and what happens if that deadline is missed?",
      "targets": ["Timing and SLA"]
    }
  ]
}
